CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE categories (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name VARCHAR(100) NOT NULL, slug VARCHAR(100) UNIQUE NOT NULL, description TEXT, is_active BOOLEAN DEFAULT TRUE, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE products (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), category_id UUID REFERENCES categories(id) ON DELETE SET NULL, name VARCHAR(150) NOT NULL, slug VARCHAR(150) UNIQUE NOT NULL, description TEXT, is_discreet BOOLEAN DEFAULT TRUE, is_active BOOLEAN DEFAULT TRUE, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE product_variants (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), product_id UUID REFERENCES products(id) ON DELETE CASCADE, sku VARCHAR(50) UNIQUE, variant_name VARCHAR(100), price NUMERIC(10,2) NOT NULL CHECK(price >= 0), stock_quantity INT DEFAULT 0 CHECK(stock_quantity >= 0), created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE delivery_zones (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name VARCHAR(100) NOT NULL, neighborhoods TEXT, fee NUMERIC(10,2) NOT NULL CHECK(fee >= 0), estimated_delay VARCHAR(50) DEFAULT '24h', is_active BOOLEAN DEFAULT TRUE);
CREATE TABLE orders (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), order_number VARCHAR(20) UNIQUE NOT NULL, delivery_zone_id UUID REFERENCES delivery_zones(id) ON DELETE SET NULL, customer_alias VARCHAR(100), customer_phone VARCHAR(20) NOT NULL, delivery_address TEXT NOT NULL, subtotal_amount NUMERIC(10,2) NOT NULL, delivery_fee NUMERIC(10,2) NOT NULL, total_amount NUMERIC(10,2) NOT NULL, payment_method VARCHAR(50) NOT NULL, payment_status VARCHAR(30) DEFAULT 'pending', order_status VARCHAR(30) DEFAULT 'processing', payment_provider VARCHAR(30), payment_reference VARCHAR(100), payment_checkout_url TEXT, payment_status_token_hash VARCHAR(64), created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE order_items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), order_id UUID REFERENCES orders(id) ON DELETE CASCADE, product_variant_id UUID REFERENCES product_variants(id) ON DELETE RESTRICT, unit_price NUMERIC(10,2) NOT NULL, quantity INT NOT NULL CHECK(quantity > 0), created_at TIMESTAMPTZ DEFAULT NOW());
CREATE INDEX idx_products_active ON products(is_active);
CREATE INDEX idx_variants_product ON product_variants(product_id);

CREATE UNIQUE INDEX idx_orders_payment_reference ON orders(payment_reference) WHERE payment_reference IS NOT NULL;
